\label{as:domain}
	For the whole text, we assume that $\Omega\subset\mathbb{R}^d$, $d\in\mathbb{N}$ is a bounded, convex domain (i.e.\ open and connected) that has a $\mathrm{C}^l$-boundary for some $l\in\mathbb{N}$ satisfying
	\begin{equation}\label{eq:domainBoundaryRegularity}
		l\geq\frac{(d+2)^2+4}{2(d+2)}.
	\end{equation}

\label{as:mobility}
	Assume that $m\in\mathrm{C}^0(\mathcal{C})\cap\mathrm{C}^2((0,M))$ is concave, that $m>0$ on $(0,M)$, $m(0)=0$, and if $M<+\infty$ then additionally $m(M)=0$. Moreover, we assume
	\begin{equation}\label{eq:mobilityLipschitzConditions}
		\sup_{u\in(0,M)}\lvertm'(u)\rvert<\infty\quad\text{and}\quad\sup_{u\in(0,M)}(-m''(u)m(u))<\infty.
	\end{equation}

\label{as:potential}
	We assume $F\in\mathrm{C}^2(0,M)$ subject to
	\begin{subequations}\label{eq:potentialBounds}
		\begin{align}
			\lvertF(u)\rvert&\leq C_1(1+u^\gamma),\label{eq:potentialUpperBound}\\
			m(u)F''(u)&\geq-c_1(1+m(u))\quad\text{for all }u\in(0,M)\label{eq:potentialLowerBound}
		\end{align}
	\end{subequations}
	for some constants $c_1,C_1\in(0,\infty)$ and an exponent $\gamma\in[1,\infty)$ with $\gamma\leq\frac{2d}{d-4}$ if $d\geq5$. With the \emph{pressure} $P:(0,M)\to\mathbb{R}$ defined by $P(u):=\int_\mathfrak{m}^um(v)F''(v)\mathop{}\!\mathrm{d} v$, we require a continuous extension $P\in\mathrm{C}^0(\mathcal{C})$. In the case $M=+\infty$, we further impose the asymptotic decay
	\begin{equation}\label{eq:asymptoticBehaviorP}
		\lim_{u\to\infty}\frac{P(u)}{u^\omega+\lvertF(u)\rvert}=0.
	\end{equation}
	for an exponent $\omega\in(2,\infty)$ satisfying $\omega\leq\min\{4\frac{d-1}{d-2},2\frac{d+2}{d-2}\}$ whenever $d\geq3$.

\label{as:coefficients}
	We assume $A,\tau\in\mathrm{C}^0(\mathcal{C})$, and there are positive reals $A_*$, $\tau_\mathrm{max}$, $\tau_\mathrm{min}$ such that
	\begin{align}
		\lvertA(u)\rvert&\leqA_*,\label{eq:assumptionA}\\
		\tau_\mathrm{min}\leq\tau(u)&\leq\tau_\mathrm{max}\qquad\text{for all }u\in\mathcal{C}.\label{eq:assumptionTau}
	\end{align}
	In particular, the primitive $K(u):=\int_0^uA(r)\mathop{}\!\mathrm{d} r$ is Lipschitz continuous.

\label{as:entropyInequality}
	In addition to Assumptions~\ref{as:domain}, \ref{as:mobility}, \ref{as:potential} and~\ref{as:coefficients}, we impose
	\begin{enumerate}
		\item either $M<+\infty$ or ($M=+\infty$ and $d\leq3$).
		\item\label{it:potentialConcavePartVanishing} $\lim_{u\to a}m(u)F_\mathrm{conc}''(u)=0$ for $a\in\{0,M\}\setminus\{+\infty\}$.
		\item $\tau$ and $K/\tau$ are Lipschitz continuous.
	\end{enumerate}

\label{th:discreteSolutions}
	Assume $\boldsymbol{u}^0=(u^0,z^0)\in\operatorname{dom}(\mathcal{E})$ and let the interpolants $(\overline{u}_\kappa,\underline{u}_\kappa,\widetilde{u}_\kappa)$, $(\overline{z}_\kappa,\underline{z}_\kappa,\widehat{z}_\kappa,\widetilde{z}_\kappa)$ be defined as above.
	\begin{subequations}
		\begin{enumerate}
			\item The interpolants enjoy the regularity
			\begin{align*}
				\overline{u}_\kappa,\underline{u}_\kappa(\cdot+\kappa),\widetilde{u}_\kappa&\in\mathrm{L}^\infty([0,\infty);\mathrm{H}^1(\Omega))\cap\mathrm{L}_\mathrm{loc}^2([0,\infty);\mathrm{H}_\mathrm{n}^2(\Omega)),\\
				\overline{z}_\kappa,\underline{z}_\kappa,\widehat{z}_\kappa,\widetilde{z}_\kappa&\in\mathrm{L}^\infty([0,\infty);\mathrm{L}^2(\Omega)),\quad\partial_t\widehat{z}_\kappa\in\mathrm{L}^2([0,\infty);\mathrm{L}^2(\Omega)),
			\end{align*}
			All $\overline{u}_\kappa,\underline{u}_\kappa,\widetilde{u}_\kappa$ stay in $\mathcal{C}$ and have mean value $\mathfrak{m}$ at any time $t\in[0,\infty)$.
			\item The following variational equations are fulfilled:
			The \emph{approximate equation for the order parameter}
			\begin{equation}\label{eq:approxEquationU}
				\int_0^\infty\int_\Omega\psi'V\overline{u}_\kappa\mathop{}\!\mathrm{d} x\mathop{}\!\mathrm{d} t=-\int_0^\infty\underline{\psi}_\kappa\boldsymbol{\mathrm{N}}[\overline{\boldsymbol{u}}_\kappa,\nabla V]\mathop{}\!\mathrm{d} t+O(\sqrt{\kappa})
			\end{equation}
			for all test functions $\psi\in\mathrm{C}_c^1((0,\infty))$ and $V\in\mathrm{C}^2(\overline{\Omega})$ with $\nabla V\cdot\mathrm{n}=0$ on ${\partial{\Omega}}$, where $\underline{\psi}_\kappa$ is the piecewise constant function defined as $\underline{\psi}_\kappa(t)=\psi\bigl(\kappa\lfloor\frac{t}{\kappa}\rfloor\bigr)$, and the implicit constant depends on the data and the test functions $\psi$, $V$, but not on $\kappa$. Furthermore, it holds the \emph{discrete relaxation law}
			\begin{equation}\label{eq:approxEquationZ}
				\partial_t\widehat{z}_\kappa=-\frac{1}{\tau(\underline{u}_\kappa)}\bigl(\overline{z}_\kappa-K(\overline{u}_\kappa)\bigr)\quad\text{in }\mathrm{L}^2(\Omega)
			\end{equation}
			for all $t\in[0,\infty)\setminus\{n\kappa\midn\in\mathbb{N}\}$.
			\item The \emph{discrete energy-dissipation inequality}
			\begin{align}\label{eq:approxFreeEnergyEDI}
				\mathcal{E}(\overline{\boldsymbol{u}}_\kappa(t))+\int_s^t\int_\Omega\biggl\{&\frac12\Bigl(\frac{\lvert\boldsymbol{\bar{\jmath}}_\kappa\rvert^2}{m(\overline{u}_\kappa)}+\frac{1}{\tau(\underline{u}_\kappa)}\lvert\overline{z}_\kappa-K(\overline{u}_\kappa)\rvert^2\Bigr)\notag\\
					&+\frac12\Bigl(\frac{\lvert\boldsymbol{\tilde{\jmath}}_\kappa\rvert^2}{m(\widetilde{u}_\kappa)}+\frac{1}{\tau(\underline{u}_\kappa)}\lvert\widetilde{z}_\kappa-K(\widetilde{u}_\kappa)\rvert^2\Bigr)\biggr\}\mathop{}\!\mathrm{d} x\mathop{}\!\mathrm{d} r\leq\mathcal{E}(\underline{\boldsymbol{u}}_\kappa(s))
			\end{align}
			holds for all $0\leq s\leq t<\infty$, where $\boldsymbol{\bar{\jmath}}_\kappa,\boldsymbol{\tilde{\jmath}}_\kappa\in\mathrm{L}^2([0,\infty);\mathrm{L}^{4/3}(\Omega))$ are determined by the \emph{constitutive flux relations}:
			\begin{equation}\label{eq:approxFluxConditions}
				\int_\Omega\boldsymbol{\zeta}\cdot\boldsymbol{\bar{\jmath}}_\kappa(t)\mathop{}\!\mathrm{d} x=\boldsymbol{\mathrm{N}}[\overline{\boldsymbol{u}}_\kappa(t),\boldsymbol{\zeta}],\qquad\int_\Omega\boldsymbol{\zeta}\cdot\boldsymbol{\tilde{\jmath}}_\kappa(t)\mathop{}\!\mathrm{d} x=\boldsymbol{\mathrm{N}}[\widetilde{\boldsymbol{u}}_\kappa(t),\boldsymbol{\zeta}]
			\end{equation}
			for all $\boldsymbol{\zeta}\in\mathrm{C}^1(\overline{\Omega};\mathbb{R}^d)$ with $\boldsymbol{\zeta}\cdot\mathrm{n}=0$ on ${\partial{\Omega}}$ and almost every $t\in[0,\infty)$.
			\item If Assumption~\ref{as:entropyInequality}~\ref{it:potentialConcavePartVanishing} holds true, then the \emph{discrete entropy-dissipation inequality} for the entropy functional defined in~\eqref{eq:defEntropy}
			\begin{equation}\label{eq:approxInternalEnergyEDI}
				\mathcal{U}(\overline{u}_\kappa(t))+\int_s^t\int_\Omega\Bigl(\lvert\Delta\overline{u}_\kappa\rvert^2+F''(\overline{u}_\kappa)\lvert\nabla\overline{u}_\kappa\rvert^2+A(\overline{u}_\kappa)(\overline{z}_\kappa-K(\overline{u}_\kappa))\Delta\overline{u}_\kappa\Bigr)\mathop{}\!\mathrm{d} x\mathop{}\!\mathrm{d} r\leq\mathcal{U}(\underline{u}_\kappa(s)),
			\end{equation}
			is fulfilled for every $0\leq s\leq t<\infty$.
		\end{enumerate}
	\end{subequations}

\label{re:discreteSolutions}
	Let $\alpha\in[0,1]$ satisfy $m(u)\lesssim1+u^\alpha$. We in addition have $\boldsymbol{\bar{\jmath}}_\kappa,\boldsymbol{\tilde{\jmath}}_\kappa\in\mathrm{L}^2([0,\infty);\mathrm{L}^\frac{2q}{\alpha+q}(\Omega))$ for every $q\in[2,+\infty]$ satisfying $\mathrm{H}^1(\Omega)\hookrightarrow\mathrm{L}^q(\Omega)$. This follows from $\overline{u}_\kappa,\widetilde{u}_\kappa\in\mathrm{L}^\infty([0,\infty);\mathrm{H}^1(\Omega))$ and H\"older's inequality
	\begin{align*}
		\int_0^\infty\Bigl(\int_\Omega\lvert\boldsymbol{\bar{\jmath}}_\kappa\rvert^\frac{2q}{\alpha+q}\mathop{}\!\mathrm{d} x\Bigr)^\frac{\alpha+q}{q}\mathop{}\!\mathrm{d} t&\leq\int_0^\infty\Bigl(\int_\Omega\lvertm(\overline{u}_\kappa)\rvert^\frac{q}{\alpha}\mathop{}\!\mathrm{d} x\Bigr)^\frac{\alpha}{q}\Bigl(\int_\Omega\frac{\lvert\boldsymbol{\bar{\jmath}}_\kappa\rvert^2}{m(\overline{u}_\kappa)}\mathop{}\!\mathrm{d} x\Bigr)\mathop{}\!\mathrm{d} t\\
		&\leq2^{1-\alpha}\sup_{t\in[0,\infty)}\lVert1+\overline{u}_\kappa(t)\rVert_{\mathrm{L}^q(\Omega)}^\alpha\int_0^\infty\int_\Omega\frac{\lvert\boldsymbol{\bar{\jmath}}_\kappa\rvert^2}{m(\overline{u}_\kappa)}\mathop{}\!\mathrm{d} x\mathop{}\!\mathrm{d} t<\infty.
	\end{align*}

\label{th:mainTheorem}
	For every sequence $({\kappa_\ell})_{\ell\in\mathbb{N}}\downarrow0$, there exists a subsequence (non-relabelled) and a triple $(u,z,\boldsymbol{j})$ with the regularity
	\begin{subequations}\label{eq:regularities}
		\begin{align}
			u&\in\mathrm{C}_{w,b}([0,\infty);\mathrm{H}^1(\Omega))\cap\mathrm{L}_\mathrm{loc}^2([0,\infty);\mathrm{H}^2(\Omega)),\label{eq:regularityU}\\
			z&\in\mathrm{L}^\infty([0,\infty);\mathrm{L}^2(\Omega))\text{ with }\partial_tz\in\mathrm{L}^2([0,\infty);\mathrm{L}^2(\Omega)),\label{eq:regularityZ}\\
			\boldsymbol{j}&\in\mathrm{L}^2([0,\infty);\mathrm{L}^{4/3}(\Omega;\mathbb{R}^d)),\label{eq:regularityFluxes}
		\end{align}
	\end{subequations}
	such that the interpolants from Theorem~\ref{th:discreteSolutions} converge in the sense as specified in Proposition~\ref{pr:convergentSubsequences}, and the following properties hold true:
	\begin{subequations}\label{eq:solutionNotion}
		\begin{enumerate}
			\item \emph{Continuity equation} for the phase-field variable, i.e.\ for every $\eta\in\mathrm{C}_c^1((0,\infty)\times\overline{\Omega})$
			\begin{equation}\label{eq:equationU}
				\int_0^\infty\int_\Omega u\partial_t\eta\mathop{}\!\mathrm{d} x\mathop{}\!\mathrm{d} t=-\int_0^\infty\int_\Omega\boldsymbol{j}\cdot\nabla\eta\mathop{}\!\mathrm{d} x\mathop{}\!\mathrm{d} t,\qquad u(0)=u^0,
			\end{equation}
			as well as the \emph{constitutive equation for the diffusive flux for a.e.\ $t>0$}
			\begin{equation}\label{eq:fluxCondition}
				\int_\Omega\boldsymbol{j}(t)\cdot\boldsymbol{\zeta}\mathop{}\!\mathrm{d} x=\boldsymbol{\mathrm{N}}[\boldsymbol{u}(t),\boldsymbol{\zeta}]
			\end{equation}
			for every $\boldsymbol{\zeta}\in\mathrm{C}_c^1(\overline{\Omega};\mathbb{R}^d)$ with $\boldsymbol{\zeta}\cdot\mathrm{n}=0$ on ${\partial{\Omega}}$.\\[1mm]
			\emph{Relaxation law for $z$}
			\begin{equation}\label{eq:equationZ}
				\partial_tz=-\frac{1}{\tau(u)}\bigl(z-K(u)\bigr)\quad\text{in }\mathrm{L}^2([0,\infty);\mathrm{L}^2(\Omega)),\qquad z(0)=z^0.
			\end{equation}
			\item The \emph{energy-dissipation inequality} for every $t\in[0,\infty)$
			\begin{equation}\label{eq:freeEnergyEDI}
				\mathcal{E}(\boldsymbol{u}(t))+\int_0^t\int_\Omega\Bigl(\frac{\lvert\boldsymbol{j}\rvert^2}{m(u)}+\frac{1}{\tau(u)}\lvertz-K(u)\rvert^2\Bigr)\mathop{}\!\mathrm{d} x\mathop{}\!\mathrm{d} s\leq\mathcal{E}(\boldsymbol{u}^0),
			\end{equation}
			\item If Assumption~\ref{as:entropyInequality} and $z^0\in\mathrm{L}^\infty(\Omega)$ are satisfied in addition, then $z\in\mathrm{L}_\mathrm{loc}^\infty([0,\infty);\mathrm{L}^\infty(\Omega))$, the convergence~\eqref{eq:convergenceCwIL2z} in $z$ holds strongly,
			and we have the \emph{entropy-dissipation inequality} for every $t\in[0,\infty)$
			\begin{equation}\label{eq:internalEnergyEDI}
				\mathcal{U}(\boldsymbol{u}(t))+\int_0^t\int_\Omega\Bigl(\lvert\Delta u\rvert^2+F''(u)\lvert\nabla u\rvert^2+A(u)(z-K(u))\Delta u\Bigr)\mathop{}\!\mathrm{d} x\mathop{}\!\mathrm{d} s\leq\mathcal{U}(\boldsymbol{u}^0).
			\end{equation}
		\end{enumerate}
	\end{subequations}

Let $\mathcal{F}:\mathcal{X}_\mathfrak{m}^M\to(-\infty,+\infty]$ be a proper, lower semicontinuous functional.
	\begin{enumerate}
		\item A \emph{semigroup} on a subset $X_0\subseteq\mathcal{X}_\mathfrak{m}^M$ is a family of maps $S^t:X_0\to X_0$, parametrised by $t\in[0,\infty)$, such that $S^0=\mathrm{id}_{X_0}$ and $S^{t+s}(u)=S^t(S^s(u))$ for every $u\in X_0$ and $s,t\geq0$.
		\item We call a semigroup $(S^t)_{t\geq0}$ on $\operatorname{dom}(\mathcal{F})$ a \emph{$\lambda$-flow for $\mathcal{F}$} for some $\lambda\in\mathbb{R}$ if it satisfies the \emph{Evolutionary Variational Inequality} (EVI)
		\begin{align}\label{eq:EVI}
			\frac12\limsup_{t\searrow0}\frac{\mathcal{W}_m^2(S^t(u),v)-\mathcal{W}_m^2(u,v)}{t}+\frac{\lambda}{2}\mathcal{W}_m^2(u,v)+\mathcal{F}(u)\leq\mathcal{F}(v)\tag{\textsf{EVI}}
		\end{align}
		for every $u,v\in\operatorname{dom}(\mathcal{F})$ with $\mathcal{W}_m(u,v)<+\infty$.
	\end{enumerate}

\label{le:flowInterchange}
	Let $\mathcal{F}:\mathcal{X}_\mathfrak{m}^M\to(-\infty,+\infty]$ be proper, lower semicontinuous and $(S_\mathcal{F}^t)_{t\geq0}$ a $\lambda$-flow for $\mathcal{F}$ for some $\lambda\in\mathbb{R}$. Moreover, let $(\boldsymbol{u}_\kappa^n)_{n\in\mathbb{N}}$ be the minimisers of \eqref{eq:TIM}. Whenever $u_\kappa^n\in\operatorname{dom}(\mathcal{F})$ then
	\begin{equation}\label{eq:flowInterchangeEstimate}
		\mathcal{F}(u_\kappa^n)-\mathcal{F}(u_\kappa^{n-1})\leq\kappa\liminf_{s\searrow0}\Bigl(\frac{\mathcal{E}[S_\mathcal{F}^s(u_\kappa^n),z_\kappa^n]-\mathcal{E}[u_\kappa^n,z_\kappa^n]}{s}\Bigr)-\frac{\lambda}{2}\mathcal{W}_m^2(u_\kappa^n,u_\kappa^{n-1}).
	\end{equation}

\label{le:freeEnergyProperties}
	The functional $\mathcal{E}$ is lower semicontinuous on $\mathcal{X}_\mathfrak{m}^M\times\mathrm{L}^2(\Omega)$ with respect to the weak* convergence in $\mathcal{M}(\overline{\Omega})$ and the weak convergence in $\mathrm{L}^2(\Omega)$. Moreover, there exists a constant $C_\mathcal{E}\in(0,\infty)$, depending only on $\Omega$, $\mathfrak{m}$, $d$ and $c_2$ (see \eqref{eq:potentialDecompositionBounds}), such that
	\begin{equation}\label{eq:freeEnergyLowerBound}
		\frac18\lVertu\rVert_{\mathrm{H}^1(\Omega)}^2+\int_\OmegaF_\mathrm{conv}(u)\mathop{}\!\mathrm{d} x+\frac12\lVertz-K(u)\rVert_{\mathrm{L}^2(\Omega)}^2\leq\mathcal{E}(\boldsymbol{u})+C_\mathcal{E}
	\end{equation}
	for every $\boldsymbol{u}=(u,z)\in\mathcal{X}_\mathfrak{m}^M\times\mathrm{L}^2(\Omega)$. In particular, $(\mathcal{X}_\mathfrak{m}^M\cap\mathrm{H}^2(\Omega))\times\mathrm{L}^2(\Omega)\subseteq\operatorname{dom}(\mathcal{E})\subseteq(\mathcal{X}_\mathfrak{m}^M\cap\mathrm{H}^1(\Omega))\times\mathrm{L}^2(\Omega)$ and $\mathcal{E}_\mathrm{min}:=\inf\mathcal{E}(\boldsymbol{u})<+\infty$.

\label{le:existenceTIM}
	Fix $\boldsymbol{v}=(v,p)\in\operatorname{dom}(\mathcal{E})$, $w\in\mathcal{X}_\mathfrak{m}^M$ and $\kappa>0$. Then the minimisation problem
	\begin{equation}
		\min_{\boldsymbol{u}}\Psi_{\kappa,\boldsymbol{v}}^w(\boldsymbol{u}),\quad\text{where }\Psi_{\kappa,\boldsymbol{v}}^w(\boldsymbol{u}):=\frac{1}{2\kappa}\mathcal{D}_w^2(\boldsymbol{u},\boldsymbol{v})+\mathcal{E}(\boldsymbol{u})
	\end{equation}
	among $\boldsymbol{u}=(u,z)\in\mathcal{X}_\mathfrak{m}^M\times\mathrm{L}^2(\Omega)$ has a solution that attains a finite value.

\label{le:aPrioriEasy}
	There exists a constant $C_2\in(0,\infty)$, only depending on $C_\mathcal{E}$, $\mathcal{E}_\mathrm{min}$, $\mathcal{E}(\boldsymbol{u}^0)$, $\tau_\mathrm{min}$ and $A_*$, such that
	\begin{subequations}
		\begin{align}
			\lVert\overline{u}_\kappa(t)\rVert_{\mathrm{H}^1(\Omega)}+\lVert\underline{u}_\kappa(t)\rVert_{\mathrm{H}^1(\Omega)}+\lVert\widetilde{u}_\kappa(t)\rVert_{\mathrm{H}^1(\Omega)}&\leq C_2\label{eq:aPrioriLIH1u}\\
			\mathcal{W}_m(\overline{u}_\kappa(t),\underline{u}_\kappa(t))+\mathcal{W}_m(\overline{u}_\kappa(t),\widetilde{u}_\kappa(t))&\leq C_2\sqrt{\kappa}\label{eq:aPrioriInterpolantsU}\\
			\mathcal{W}_m(\overline{u}_\kappa(s),\overline{u}_\kappa(t))&\leq C_2\sqrt{\kappa+\lverts-t\rvert}\label{eq:aPrioriCauchyWu}\\
			\lVert\overline{z}_\kappa(t)\rVert_{\mathrm{L}^2(\Omega)}+\lVert\underline{z}_\kappa(t)\rVert_{\mathrm{L}^2(\Omega)}+\lVert\widehat{z}_\kappa(t)\rVert_{\mathrm{L}^2(\Omega)}+\lVert\widetilde{z}_\kappa(t)\rVert_{\mathrm{L}^2(\Omega)}&\leq C_2\label{eq:aPrioriLIL2z}\\
			\lVert\overline{z}_\kappa(t)-\underline{z}_\kappa(t)\rVert_{\mathrm{L}^2(\Omega)}+\lVert\overline{z}_\kappa(t)-\widehat{z}_\kappa(t)\rVert_{\mathrm{L}^2(\Omega)}+\lVert\overline{z}_\kappa(t)-\widetilde{z}_\kappa(t)\rVert_{\mathrm{L}^2(\Omega)}&\leq C_2\sqrt{\kappa}\label{eq:aPrioriInterpolantsZ}\\
			\lVert\dot\widehat{z}_\kappa\rVert_{\mathrm{L}^2([0,\infty);\mathrm{L}^2(\Omega))}&\leq C_2\label{eq:aPrioriL2L2dotz}
		\end{align}
	\end{subequations}
	for every $s,t\in[0,\infty)$.

\label{le:nabla2mEstimate}
	There exists a constant $C_3\in(0,\infty)$, depending only on $\Omega$, $d$, $M$, $\mathfrak{m}$ and $m(\mathfrak{m})$, such that
	\begin{equation}\label{eq:nabla2mEstimate}
		\Bigl\lVert\frac{\lvert\nabla v\rvert^2}{m(v)}\Bigr\rVert_{\mathrm{L}^q(\Omega)}\leq C_3\bigl(\lVert\Delta v\rVert_{\mathrm{L}^2(\Omega)}+\lVert\nabla v\rVert_{\mathrm{L}^{2q}(\Omega;\mathbb{R}^d)}^2\bigr)
	\end{equation}
	for every $v\in\mathrm{H}_\mathrm{n}^2(\Omega)$ and $q\in[1,2]$, with convention $\frac{0}{0}:=0$.

\label{le:freeEnergyAlongHeatFlow}
	Let $v$ be the solution to the heat equation~\eqref{eq:heatEquation} with homogeneous Neumann condition and some initial value $v^0\in\mathcal{X}_\mathfrak{m}^M\cap\mathrm{H}^1(\Omega)$. Moreover, let $z\in\mathrm{L}^2(\Omega)$. If
	\begin{equation}\label{eq:freeEnergyLiminfAlongHeatFlowBounded}
		\liminf_{s\searrow0}\frac{1}{s}\bigl(\mathcal{E}[v_s,z]-\mathcal{E}[v^0,z]\bigr)>-\infty,
	\end{equation}
	then $v^0\in\mathrm{H}_\mathrm{n}^2(\Omega)$, and we have the estimate
	\begin{equation}\label{eq:freeEnergyLiminfAlongHeatFlowQualitativeEstimate}
		-\liminf_{s\searrow0}\frac{1}{s}\bigl(\mathcal{E}[v_s,z]-\mathcal{E}[v^0,z]\bigr)\geq\frac{1}{2}\int_\Omega\lvert\Delta v^0\rvert^2\mathop{}\!\mathrm{d} x-C_4(1+\mathcal{E}[v^0,z])
	\end{equation}
	for a constant $C_4\in(0,\infty)$ depending only on $C_3$ (from Lemma~\ref{le:nabla2mEstimate}), $C_\mathcal{E}$, $c_1$ and $A_*$. If Assumption~\ref{as:entropyInequality}~\ref{it:potentialConcavePartVanishing} holds in addition, we have the sharp inequality
	\begin{multline}\label{eq:freeEnergyLiminfAlongHeatFlowRefinedEstimate}
		-\liminf_{s\searrow0}\frac{1}{s}\bigl(\mathcal{E}[v_s,z]-\mathcal{E}[v^0,z]\bigr)\\
		\geq\int_\Omega\lvert\Delta v^0\rvert^2\mathop{}\!\mathrm{d} x+\int_\Omega F''(v^0)\lvert\nabla v^0\rvert^2\mathop{}\!\mathrm{d} x+\int_\Omega(z-K(v^0))A(v^0)\Delta v^0\mathop{}\!\mathrm{d} x.
	\end{multline}

\label{le:aPrioriH2}
	It holds $\widetilde{u}_\kappa(t)\in\mathrm{H}_\mathrm{n}^2(\Omega)$ for every $\kappa>0$, $t\in(0,\infty)$ (in particular for every $u_\kappa^n$, $n\in\mathbb{N}$, since $\widetilde{u}_\kappa(n\kappa)=u_\kappa^n$). There exists a constant $C_5\in(0,\infty)$ such that
	\begin{equation}
		\lVert\overline{u}_\kappa\rVert_{\mathrm{L}^2([0,T];\mathrm{H}^2(\Omega))}+\lVert\underline{u}_\kappa\rVert_{\mathrm{L}^2([\kappa,T];\mathrm{H}^2(\Omega))}\leq C_5(T+\kappa+1)\label{eq:aPrioriL2H2olu&ulu}
	\end{equation}
	for every $\kappa>0$ and every $T>0$.

Fix $n\in\mathbb{N}_0$, $\theta\in(0,\kappa]$, and set $t:=n\kappa+\theta$. First, we apply the flow interchange Lemma~\ref{le:flowInterchange} to the heat flow $(S_\mathcal{U}^t)_{t\geq0}$ from~\eqref{eq:defInternalEnergy}. Together with the bounds for $\mathcal{U}$ in~\eqref{eq:internalEnergyUpperBound} this yields
	\[\liminf_{s\searrow0}\Bigl(\frac{\mathcal{E}[S_\mathcal{U}^s(\widetilde{u}_\kappa(t)),\widetilde{z}_\kappa(t)]-\mathcal{E}[\widetilde{u}_\kappa(t),\widetilde{z}_\kappa(t)]}{s}\Bigr)\geq\frac{1}{\theta}\bigl(\mathcal{U}(\widetilde{u}_\kappa(t))-\mathcal{U}(u_\kappa^n)\bigr)\geq-\frac{C_\mathcal{U}}{\theta}(1+\lVertu_\kappa^n\rVert_{\mathrm{L}^2(\Omega)}^2).\]
	Hence, the condition~\eqref{eq:freeEnergyLiminfAlongHeatFlowBounded} in Lemma~\ref{le:freeEnergyAlongHeatFlow} is fulfilled. It follows $\widetilde{u}_\kappa(t)\in\mathrm{H}_\mathrm{n}^2(\Omega)$ and the estimate~\eqref{eq:freeEnergyLiminfAlongHeatFlowQualitativeEstimate}. Together with the flow interchange estimate~\eqref{eq:flowInterchangeEstimate} this amounts to
	\begin{align}\label{eq:aPrioriL2H2Prelim}
		\lVert\Delta u_\kappa^k\rVert_{\mathrm{L}^2(\Omega)}^2&\leq2C_4(1+\mathcal{E}(\boldsymbol{u}^0))+\frac{2}{\kappa}\bigl(\mathcal{U}(u_\kappa^{k-1})-\mathcal{U}(u_\kappa^k)\bigr)
	\end{align}
	for every $k\in\mathbb{N}$. If $t$ is as before, we obtain by telescoping
	\begin{align*}
		\int_0^t\lVert\Delta\overline{u}_\kappa(t)\rVert_{\mathrm{L}^2(\Omega)}^2\mathop{}\!\mathrm{d} t&\leq\kappa\sum_{k=1}^{n+1}\lVert\Delta u_\kappa^k\rVert_{\mathrm{L}^2(\Omega)}^2\\
		&\leq2(n+1)\kappa C_4(1+\mathcal{E}(\boldsymbol{u}^0))+2\sum_{k=1}^{n+1}\bigl(\mathcal{U}(u_\kappa^{k-1})-\mathcal{U}(u_\kappa^k)\bigr)\\
		&\leq2(t+\kappa)C_4(1+\mathcal{E}(\boldsymbol{u}^0))+2C_\mathcal{U}(1+C_1^2),
	\end{align*}
	where we used the bounds for $\mathcal{U}$ from~\eqref{eq:internalEnergyUpperBound} and the a priori estimate~\eqref{eq:aPrioriLIH1u}. Hence, \eqref{eq:aPrioriL2H2olu&ulu} follows for $\overline{u}_\kappa$ from~\eqref{eq:H2DeltaEstimate}, and for $\underline{u}_\kappa$ since $\lVert\underline{u}_\kappa\rVert_{\mathrm{L}^2([\kappa,T];\mathrm{H}^2(\Omega))}=\lVert\overline{u}_\kappa\rVert_{\mathrm{L}^2([0,T-\kappa];\mathrm{H}^2(\Omega))}$.

Under Assumption~\ref{as:entropyInequality}~\ref{it:potentialConcavePartVanishing}, we have for every $\kappa>0$, $n\in\mathbb{N}$,
	\begin{align*}
		\mathcal{U}(\boldsymbol{u}_\kappa^n)+\kappa\int_\Omega\Bigl\{\lvert\Delta u_\kappa^n\rvert^2+F''(u_\kappa^n)\lvert\nabla u_\kappa^n\rvert^2+(z_\kappa^n-K(u_\kappa^n))A(u_\kappa^n)\Delta u_\kappa^n\Bigr\}\mathop{}\!\mathrm{d} x\leq\mathcal{U}(\boldsymbol{u}_\kappa^{n-1}).
	\end{align*}

\label{pr:aPrioriH2DeGiorgiPrelim}
